queries.query:
SELECT ?p (COUNT(*) AS ?n)
WHERE { ?s ?p ?o }
GROUP BY ?p ORDER BY DESC(?n) LIMIT 20

SELECT ?t (COUNT(*) AS ?n)
WHERE { ?s a ?t }
GROUP BY ?t ORDER BY DESC(?n) LIMIT 20

# Endpoint: FPKG · graph: transparency#graph/appg-register
PREFIX t: <https://forgetmenot.example/transparency#>
SELECT ?title ?category ?purpose
WHERE {
  GRAPH <https://forgetmenot.example/transparency#graph/appg-register> {
    ?g a t:APPG ;
       t:title ?title ;
       t:category ?category ;
       t:purpose ?purpose .
  }
} ORDER BY ?category ?title LIMIT 100

# Endpoint: FPKG · graph: transparency#graph/appg-register
PREFIX t: <https://forgetmenot.example/transparency#>
SELECT ?source (SUM(?gbp) AS ?totalGbp)
WHERE {
  GRAPH <https://forgetmenot.example/transparency#graph/appg-register> {
    ?b a t:FinancialBenefit ;
       t:benefitSource ?source ;
       t:benefitValueGbp ?gbp .
  }
} GROUP BY ?source ORDER BY DESC(?totalGbp) LIMIT 25

PREFIX t: <https://forgetmenot.example/transparency#>
SELECT ?title ?purpose
WHERE {
  GRAPH <https://forgetmenot.example/transparency#graph/appg-register> {
    ?g a t:APPG ; t:title ?title ; t:purpose ?purpose .
    FILTER(CONTAINS(LCASE(?purpose), LCASE("{{keyword}}")))
  }
} ORDER BY ?title LIMIT 50

# Endpoint: FPKG · graph: psephology/candidacies
PREFIX el: <http://parliament.uk/ontologies/election/>
SELECT ?election (COUNT(?c) AS ?n)
WHERE {
  GRAPH <https://forgetmenot.local/graph/psephology/candidacies> {
    ?c a el:Candidacy ; el:inElection ?election .
  }
} GROUP BY ?election ORDER BY DESC(?n) LIMIT 15

PREFIX el: <http://parliament.uk/ontologies/election/>
SELECT ?given ?family ?share ?votes
WHERE {
  GRAPH <https://forgetmenot.local/graph/psephology/candidacies> {
    ?c a el:Candidacy ;
       el:resultPosition 1 ;
       el:voteShare ?share ;
       el:voteCount ?votes ;
       el:candidateGivenName ?given ;
       el:candidateFamilyName ?family .
  }
} ORDER BY DESC(?share) LIMIT 25

