# Endpoint: FPKG · graph: identity/members-api
PREFIX v: <https://forgetmenot.local/vocab#>
PREFIX parl: <https://id.parliament.uk/schema/>
PREFIX schema: <http://schema.org/>
SELECT ?name ?party ?constituency ?mnisId
WHERE {
  GRAPH <https://forgetmenot.local/graph/identity/members-api> {
    ?p schema:name ?name ;
       v:party ?party ;
       v:constituency ?constituency ;
       parl:mnisId ?mnisId .
  }
} ORDER BY ?name LIMIT 100

