PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?concept ?label
WHERE {
  GRAPH <https://lda.data.parliament.uk/graph/legacy-terms/core> {
    ?concept skos:prefLabel ?label .
    FILTER(CONTAINS(LCASE(STR(?label)), LCASE("{{frag}}")))
  }
} ORDER BY ?label LIMIT 50

PREFIX parl: <https://id.parliament.uk/schema/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?person ?p ?o
WHERE {
  ?person parl:mnisId "{{mnis}}"^^xsd:integer ; ?p ?o .
} LIMIT 60

# defaultView:ImageGrid
PREFIX wd:   <http://www.wikidata.org/entity/>
PREFIX wdt:  <http://www.wikidata.org/prop/direct/>
PREFIX p:    <http://www.wikidata.org/prop/>
PREFIX ps:   <http://www.wikidata.org/prop/statement/>
PREFIX pq:   <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?pm ?pmLabel ?image ?start WHERE {
  ?pm p:P39 ?term .
  ?term ps:P39 wd:Q14211 ; pq:P580 ?start .
  OPTIONAL { ?pm wdt:P18 ?image }
  OPTIONAL { ?pm rdfs:label ?pmLabel . FILTER (lang(?pmLabel) = "en") }
} ORDER BY DESC(?start) LIMIT 30

PREFIX wd:   <http://www.wikidata.org/entity/>
PREFIX p:    <http://www.wikidata.org/prop/>
PREFIX ps:   <http://www.wikidata.org/prop/statement/>
PREFIX pq:   <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?personLabel ?constituency ?constituencyLabel WHERE {
  ?person p:P39 ?m .
  ?m ps:P39 wd:Q16707842 ; pq:P768 ?constituency .
  FILTER NOT EXISTS { ?m pq:P582 [] }
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER (lang(?personLabel) = "en") }
  OPTIONAL { ?constituency rdfs:label ?constituencyLabel . FILTER (lang(?constituencyLabel) = "en") }
} ORDER BY ?personLabel

PREFIX wdt:  <http://www.wikidata.org/prop/direct/>
PREFIX wd:   <http://www.wikidata.org/entity/>
PREFIX p:    <http://www.wikidata.org/prop/>
PREFIX ps:   <http://www.wikidata.org/prop/statement/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?pm ?pmLabel WHERE {
  ?pm p:P39/ps:P39 wd:Q14211 .
  ?pm wdt:P40+ wd:Q10633 .
  OPTIONAL { ?pm rdfs:label ?pmLabel . FILTER(lang(?pmLabel) = "en") }
}

# Federated: Wikidata (left) → UK Parliament DDP (SERVICE)
# Join key: P10428 (MNIS numeric id) on Wikidata = parl:mnisId in DDP.
PREFIX wd:   <http://www.wikidata.org/entity/>
PREFIX wdt:  <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX parl: <https://id.parliament.uk/schema/>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
SELECT ?personLabel ?ddpPerson WHERE {
  VALUES ?person { wd:{{qid}} }
  ?person wdt:P10428 ?mnis .
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel)="en") }
  SERVICE <https://api.parliament.uk/sparql> {
    ?ddpPerson parl:mnisId ?mnisInt .
    FILTER(STR(?mnisInt) = ?mnis)
  }
} LIMIT 10
